#[test]
fn unit_metadata() {
    let info = Ratio::<f64>::INFO;
    assert_eq!(info.name, "Ratio");
    assert_eq!(info.units.len(), RatioUnit::ALL.len());
    for (&unit, unit_info) in RatioUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, RatioUnit::DecimalFraction.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Ratio::new(v, RatioUnit::DecimalFraction),
        Ratio::from_decimal_fractions(v)
    );
    assert_eq!(
        Ratio::from_base(v).convert_to(RatioUnit::DecimalFraction),
        Ratio::from_base(v).as_decimal_fractions()
    );
    assert_eq!(Ratio::new(v, RatioUnit::Percent), Ratio::from_percent(v));
    assert_eq!(
        Ratio::from_base(v).convert_to(RatioUnit::Percent),
        Ratio::from_base(v).as_percent()
    );
    assert_eq!(
        Ratio::new(v, RatioUnit::PartPerThousand),
        Ratio::from_parts_per_thousand(v)
    );
    assert_eq!(
        Ratio::from_base(v).convert_to(RatioUnit::PartPerThousand),
        Ratio::from_base(v).as_parts_per_thousand()
    );
    assert_eq!(
        Ratio::new(v, RatioUnit::PartPerMillion),
        Ratio::from_parts_per_million(v)
    );
    assert_eq!(
        Ratio::from_base(v).convert_to(RatioUnit::PartPerMillion),
        Ratio::from_base(v).as_parts_per_million()
    );
    assert_eq!(
        Ratio::new(v, RatioUnit::PartPerBillion),
        Ratio::from_parts_per_billion(v)
    );
    assert_eq!(
        Ratio::from_base(v).convert_to(RatioUnit::PartPerBillion),
        Ratio::from_base(v).as_parts_per_billion()
    );
    assert_eq!(
        Ratio::new(v, RatioUnit::PartPerTrillion),
        Ratio::from_parts_per_trillion(v)
    );
    assert_eq!(
        Ratio::from_base(v).convert_to(RatioUnit::PartPerTrillion),
        Ratio::from_base(v).as_parts_per_trillion()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [Ratio; 6] = [
        Ratio::const_new(1234.5, RatioUnit::DecimalFraction),
        Ratio::const_new(1234.5, RatioUnit::Percent),
        Ratio::const_new(1234.5, RatioUnit::PartPerThousand),
        Ratio::const_new(1234.5, RatioUnit::PartPerMillion),
        Ratio::const_new(1234.5, RatioUnit::PartPerBillion),
        Ratio::const_new(1234.5, RatioUnit::PartPerTrillion),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(RatioUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            Ratio::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in RatioUnit::ALL {
            assert_eq!(
                Ratio::const_new(v, unit).as_base().to_bits(),
                Ratio::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Ratio::from_base(v);
        let auto = q.auto_unit();
        assert_close(Ratio::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in RatioUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Ratio::from_base(0.0).auto_unit().unit,
        RatioUnit::DecimalFraction
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!("%".parse::<RatioUnit>(), Ok(RatioUnit::Percent));
    assert_eq!(
        format!("2.5 {}", "%").parse::<Ratio>(),
        Ok(Ratio::new(2.5, RatioUnit::Percent))
    );
    assert_eq!("‰".parse::<RatioUnit>(), Ok(RatioUnit::PartPerThousand));
    assert_eq!(
        format!("2.5 {}", "‰").parse::<Ratio>(),
        Ok(Ratio::new(2.5, RatioUnit::PartPerThousand))
    );
    assert_eq!("ppm".parse::<RatioUnit>(), Ok(RatioUnit::PartPerMillion));
    assert_eq!(
        format!("2.5 {}", "ppm").parse::<Ratio>(),
        Ok(Ratio::new(2.5, RatioUnit::PartPerMillion))
    );
    assert_eq!("ppb".parse::<RatioUnit>(), Ok(RatioUnit::PartPerBillion));
    assert_eq!(
        format!("2.5 {}", "ppb").parse::<Ratio>(),
        Ok(Ratio::new(2.5, RatioUnit::PartPerBillion))
    );
    assert_eq!("ppt".parse::<RatioUnit>(), Ok(RatioUnit::PartPerTrillion));
    assert_eq!(
        format!("2.5 {}", "ppt").parse::<Ratio>(),
        Ok(Ratio::new(2.5, RatioUnit::PartPerTrillion))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Ratio>(),
        Err(ParseError::UnknownUnit)
    );
}

